const futureHint=`<div class="notice future-notice">${icon('lock',20)}<div><b>EXPANSÃO NÃO CONTRATADA • SIMULAÇÃO NAVEGÁVEL</b><small>Não é um módulo liberado à Clínica Áudio S.A. Os dados são fictícios, armazenados apenas enquanto esta aba estiver aberta. Nenhuma mensagem, assinatura ou atendimento real será realizado.</small></div></div>`;
function categoryTile(item){return `<button class="category-tile" type="button" data-page="${item.id}"><span class="category-icon">${icon(item.ic,25)}</span><span class="category-copy"><strong>${esc(item.name)}</strong><small>${esc(item.summary)}</small><span class="category-link">Explorar demonstração →</span></span></button>`;}
function inicio(){return pageHeader('PORTAL DO PRODUTO / ÁUDIO S.A.','Bem-vindo à plataforma','Uma solução modular com foco inicial na categoria Financeira; veja também como o ecossistema pode evoluir.')+demoNote+
 `<section class="landing-hero"><div class="landing-copy"><span class="landing-kicker">CATEGORIA PRINCIPAL • FASE INICIAL</span><h2>Financeiro que acompanha o ritmo da clínica.</h2><p>Controle de caixa, recebíveis, despesas, parcelas, repasses e Stone com uma experiência clara, fluida e preparada para uso remoto.</p><div class="landing-actions">${button('Entrar no Financeiro →',state.role==='recepcao'?'lancamentos':state.role==='profissional'?'documentos':'dashboard',true)}${button('Ver portfólio completo','portfolio')}</div><span class="landing-foot">Entrega inicial contratada: Financeiro · Demais categorias: prévias de expansão</span></div><div class="landing-deco" aria-hidden="true"><span>${icon('wallet',54)}</span><b>UMA PLATAFORMA</b><em>múltiplos caminhos</em></div></section>`+
 `<div class="section-header"><div><span class="eyebrow">VISÃO DAS CATEGORIAS</span><h2>Conheça a plataforma completa</h2><p>As demonstrações abaixo não representam contratação, homologação ou liberação dos módulos.</p></div>${button('Explorar portfólio →','portfolio')}</div><div class="category-grid">${clinicalCatalog.slice(0,3).map(categoryTile).join('')}</div>`;
}
function portfolio(){return pageHeader('PLATAFORMA MODULAR / CATÁLOGO','Categorias do ecossistema','Explore telas demonstrativas de serviços e operações que poderão ser contratados futuramente.',button('Voltar ao início','inicio'))+demoNote+
 `<div class="category-highlight"><span class="badge ok">MÓDULO INICIAL CONTRATADO</span><h2>Gestão financeira integrada</h2><p>Dashboard, lançamentos, contas, parcelas, Stone, repasses, histórico, relatórios, documentos e ajustes. A V1 ainda é exclusivamente uma simulação.</p>${button('Abrir categoria Financeira →',state.role==='recepcao'?'lancamentos':state.role==='profissional'?'documentos':'dashboard',true)}</div>`+
 `<div class="section-header"><div><span class="eyebrow">CATEGORIAS DE EXPANSÃO</span><h2>Prévia da versão completa</h2><p>Clique em cada categoria para abrir uma demonstração funcional, sem ativar licenças.</p></div></div><div class="category-grid">${clinicalCatalog.map(categoryTile).join('')}</div>`;
}
const demoHead=(id)=>{const c=clinicalCatalog.find(x=>x.id===id);return pageHeader('LABORATÓRIO DE EXPANSÃO / '+c.name.toUpperCase(),c.name,c.detail,button('← Todas as categorias','portfolio'))+futureHint;};
const demoRecords=(items,renderer)=>`<div class="records-grid">${items.map(renderer).join('')}</div>`;
const demoRecord=(label,small,info,actions='')=>`<article class="record-card"><div class="record-top"><div class="record-title"><h3>${esc(label)}</h3><p>${esc(small)}</p></div><span class="badge neutral">${esc(info)}</span></div>${actions?`<div class="record-actions">${actions}</div>`:''}</article>`;
function agenda(){return demoHead('agenda')+panel('Agenda por profissional',demoRecords(clinicDemo.appointments,x=>demoRecord(x.name,x.professional+' · '+shortDate(x.date)+' às '+x.time+' · '+x.type,x.status,button('Alterar situação','demo-appointment:'+x.id,false,true)))+`<div class="record-actions">${button('+ Agendar exemplo','demo-add-appointment',true)}</div><div class="helper">Remarcações individuais ou em lote, duração por procedimento e confirmação via WhatsApp serão implementadas apenas se contratadas.</div>`);}
function pacientes(){return demoHead('pacientes')+panel('Cadastros ilustrativos',demoRecords(clinicDemo.patients,x=>demoRecord(x.name,x.id,x.status,button('Visualizar ficha','demo-patient:'+x.id,false,true)))+`<div class="record-actions">${button('+ Cadastrar paciente fictício','demo-add-patient',true)}</div><div class="helper">Não digite nomes, CPF, contatos ou informações reais de pacientes neste protótipo público.</div>`);}
function atendimento(){return demoHead('atendimento')+panel('Fila da operação remota',demoRecords(clinicDemo.queue,x=>demoRecord(x.name,x.type+' · '+x.id,x.status,button('Avançar etapa','demo-queue:'+x.id,false,true)))+`<div class="helper">Nenhuma ligação, teleconsulta, prontuário, WhatsApp ou notificação será aberta ou enviada. Os estados servem apenas para testar a navegação.</div>`);}
function aasi(){return demoHead('aasi')+panel('Modelos e documentos futuros',demoRecords(clinicDemo.terms,x=>demoRecord(x.name,x.id,x.status,button('Prévia do documento','demo-term:'+x.id,false,true)))+`<div class="record-actions">${button('+ Criar rascunho fictício','demo-add-term',true)}</div><div class="helper warning">Assinatura eletrônica e termos clínicos reais exigem aprovação jurídica, revisão profissional e governança de documentos.</div>`);}
function estoque(){return demoHead('estoque')+panel('Controle ilustrativo de aparelhos',demoRecords(clinicDemo.stock,x=>demoRecord(x.name,x.id,'Saldo simulado: '+x.qty,button('Entrada +1','demo-stock-in:'+x.id,false,true)+button('Saída −1','demo-stock-out:'+x.id,false,true)))+`<div class="helper">Não contém números de série ou informações de produtos reais. Movimentações existem apenas nesta sessão.</div>`);}
function comunicacao(){return demoHead('comunicacao')+panel('Central de solicitações e rascunhos',`<div class="helper">Prévia de comunicação remota para equipes, pacientes e atendimento. Nenhuma mensagem sai do navegador.</div><div class="record-actions">${button('+ Criar rascunho simulado','demo-draft',true)}</div>`+demoRecords(clinicDemo.drafts,x=>demoRecord(x.subject,x.text,'Não enviado'))+`<div class="helper">Integração com WhatsApp e canal de atendimento será definida em fase futura, com consentimentos e controles apropriados.</div>`);}
function central(){if(state.role!=='desenvolvedor')return noData('Área informativa reservada ao perfil Desenvolvedor nesta demonstração.');return pageHeader('ADMINISTRAÇÃO / ACESSO LOCAL','Auditoria exclusivamente na Central','A aba de Auditoria foi removida do aplicativo clínico. A Central A.dev V4.5.1 permanece intacta, instalada no XAMPP.')+`<section class="panel"><div class="panel-head"><h2>Central A.dev — ambiente local</h2><span class="badge warn">SOMENTE XAMPP</span></div><p class="subline">Para acessar a auditoria, abra a Central em seu próprio computador. Um visitante do GitHub Pages não terá acesso à sua instalação local.</p><div class="helper warning">O perfil selecionado nesta demonstração não autentica o usuário na Central. Somente a autenticação real e as permissões do backend poderão tornar o acesso à auditoria exclusivo do Desenvolvedor.</div><a class="btn btn-primary" href="https://127.0.0.1/central_gestao/" target="_blank" rel="noopener noreferrer">Abrir Central A.dev no XAMPP ↗</a></section>`;}
function demoAdd(kind){if(kind==='appointment')openDrawer('Agendamento fictício',`<form id="demo-appointment-form"><div class="form-grid">${field('demo-nome','Identificação fictícia','text','Paciente fictício 03','required maxlength="65"')}${field('demo-data','Data','date','2026-11-22','required')}${field('demo-hora','Hora','time','09:00','required')}</div><div class="drawer-footer"><button class="btn btn-primary" type="submit">Adicionar à agenda (demo)</button></div></form>`);
 else if(kind==='patient')openDrawer('Cadastro fictício',`<form id="demo-patient-form"><div class="helper warning">Use somente um nome genérico de teste; dados reais não devem ser informados.</div>${field('demo-pessoa','Nome de demonstração','text','Paciente fictício 03','required maxlength="65"')}<div class="drawer-footer"><button class="btn btn-primary" type="submit">Criar cadastro (demo)</button></div></form>`);
 else if(kind==='term')openDrawer('Modelo clínico fictício',`<form id="demo-term-form">${field('demo-termo','Nome do modelo','text','Termo AASI — exemplo','required maxlength="90"')}<div class="drawer-footer"><button class="btn btn-primary" type="submit">Criar rascunho (demo)</button></div></form>`);
 else if(kind==='draft')openDrawer('Rascunho de comunicação',`<form id="demo-draft-form">${field('demo-assunto','Assunto','text','Retorno de atendimento (exemplo)','required maxlength="90"')}<div class="field spaced"><label for="demo-mensagem">Mensagem demonstrativa</label><textarea id="demo-mensagem" required maxlength="500">Olá! Esta é uma mensagem fictícia.</textarea></div><div class="drawer-footer"><button class="btn btn-primary" type="submit">Guardar somente na memória</button></div></form>`);
}
function demoSave(form){if(!form.reportValidity())return;const v=id=>$(id).value.trim();const uid=(prefix,list)=>prefix+'-'+String(list.length+1).padStart(3,'0');
 if(form.id==='demo-appointment-form')clinicDemo.appointments.push({id:uid('AG',clinicDemo.appointments),name:v('demo-nome'),professional:'A definir',date:v('demo-data'),time:v('demo-hora'),type:'Consulta demonstrativa',status:'Agendado'});
 else if(form.id==='demo-patient-form')clinicDemo.patients.push({id:uid('PX',clinicDemo.patients),name:v('demo-pessoa'),status:'Cadastro de demonstração'});
 else if(form.id==='demo-term-form')clinicDemo.terms.push({id:uid('AASI',clinicDemo.terms),name:v('demo-termo'),status:'Rascunho'});
 else if(form.id==='demo-draft-form')clinicDemo.drafts.push({id:uid('COM',clinicDemo.drafts),subject:v('demo-assunto'),text:v('demo-mensagem')});
 closeDrawer();render();notify('Exemplo criado somente em memória. Nenhuma operação real foi executada.');
}
function demoAction(action){const [type,id]=action.split(':');
 if(type==='demo-add-appointment')return demoAdd('appointment');if(type==='demo-add-patient')return demoAdd('patient');if(type==='demo-add-term')return demoAdd('term');if(type==='demo-draft')return demoAdd('draft');
 if(type==='demo-appointment'){let x=clinicDemo.appointments.find(x=>x.id===id);if(x)x.status=x.status==='Confirmado'?'Remarcado':'Confirmado';}
 if(type==='demo-queue'){let x=clinicDemo.queue.find(x=>x.id===id);if(x)x.status=x.status==='Concluído'?'Aguardando':x.status==='Em atendimento'?'Concluído':'Em atendimento';}
 if(type==='demo-stock-in'||type==='demo-stock-out'){let x=clinicDemo.stock.find(x=>x.id===id);if(x)x.qty=Math.max(0,x.qty+(type==='demo-stock-in'?1:-1));}
 if(type==='demo-patient'){let x=clinicDemo.patients.find(x=>x.id===id);if(x)openDrawer('Ficha fictícia — '+x.id,`<div class="paper"><h3>${esc(x.name)}</h3><p>Identificação demonstrativa: ${esc(x.id)}</p><p>Sem endereço, contato ou prontuário real.</p></div><div class="drawer-footer">${button('Fechar','closeDrawer',true)}</div>`);return;}
 if(type==='demo-term'){let x=clinicDemo.terms.find(x=>x.id===id);if(x)openDrawer('Prévia de termo AASI',`<div class="paper"><small>RASCUNHO FICTÍCIO · SEM VALIDADE</small><h3>${esc(x.name)}</h3><p>Modelo para demonstrar apresentação e conferência de um termo de teste AASI. Não contém identificação clínica nem assinatura.</p><div class="paper-line"></div><p>Etapas previstas: revisão profissional → validação da clínica → apresentação → eventual assinatura por fluxo homologado.</p></div><div class="drawer-footer">${button('Fechar prévia','closeDrawer',true)}</div>`);return;}
 render();notify('Estado alterado somente nesta sessão de demonstração.');
}
const views={inicio,portfolio,dashboard,lancamentos,contas,parcelas,stone,repasses,historico,relatorios,documentos,config:configuracoes,acesso,central,agenda,pacientes,atendimento,aasi,estoque,comunicacao};
function activePermission(){return permissions[state.role]||[];}
function render(){if(!activePermission().includes(state.page))state.page=activePermission()[0]||'acesso';
 $('main-nav').innerHTML=menus.filter(x=>activePermission().includes(x[0])).map(([id,label,ic])=>`<button type="button" class="nav-item ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span><span>${label}</span></button>`).join('');
 $('crumb-current').textContent=title(state.page).toUpperCase();$('top-heading').textContent=state.role==='recepcao'?'Registro operacional remoto':state.role==='profissional'?'Acesso do profissional':state.role==='desenvolvedor'?'Visão técnica demonstrativa':'Gestão operacional e financeira';
 $('main').innerHTML=views[state.page]();closeNav();}
function go(page){if(!activePermission().includes(page)){notify('Este perfil de demonstração não possui acesso a essa tela.');return;}state.page=page;location.hash='/'+page;render();window.scrollTo({top:0,behavior:'instant'});}
function closeNav(){$('sidebar').classList.remove('is-open');$('mobile-scrim').hidden=true;$('menu-toggle').setAttribute('aria-expanded','false')}
function openNav(){$('sidebar').classList.add('is-open');$('mobile-scrim').hidden=false;$('menu-toggle').setAttribute('aria-expanded','true')}
function openDrawer(heading,body){$('drawer-title').textContent=heading;$('drawer-body').innerHTML=body;$('drawer').hidden=false;$('drawer-backdrop').hidden=false;document.body.style.overflow='hidden';$('drawer-close').focus();}
function closeDrawer(){$('drawer').hidden=true;$('drawer-backdrop').hidden=true;document.body.style.overflow='';}
function setTheme(){document.documentElement.dataset.theme=state.theme;$('theme-toggle').textContent=state.theme==='dark'?'☀':'☾';$('theme-toggle').title=state.theme==='dark'?'Ativar modo claro':'Ativar modo escuro';}
function bump(){state.revision+=1;render();}
function select(name,items,value=''){return `<select id="${name}">${items.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`;}
function field(name,label,type='text',value='',more=''){return `<div class="field ${more.includes('required')?'required':''}"><label for="${name}">${label}</label><input id="${name}" type="${type}" value="${esc(value)}" ${more}></div>`;}
function newTransaction(editId){if(state.role==='profissional'){notify('Profissional sem permissão para lançamentos.');return;}const old=state.tx.find(x=>x.id===editId);if(editId&&!old)return; if(old&&old.status!=='pendente'){notify('Lançamentos liquidados não podem ser editados diretamente.');return;}
 const kind=old?.kind||'entrada';const methods=[['pix','Pix'],['cartao','Cartão'],['boleto','Boleto'],['transferencia','Transferência'],['dinheiro','Dinheiro']];
 openDrawer(old?'Editar lançamento pendente':'Novo lançamento',`<div class="helper">Registro apenas na memória desta sessão. Para operação real, será necessária autenticação e verificação no backend.</div><form id="transaction-form"><div class="form-grid"><div class="field required"><label>Natureza</label>${select('f-kind',[['entrada','Entrada'],['saida','Saída']],kind)}</div><div class="field required"><label>Data</label><input id="f-date" type="date" required value="${old?.date||DEMO_DATE}"></div><div class="field wide required"><label>Descrição</label><input id="f-description" maxlength="120" required placeholder="Descreva a operação fictícia" value="${esc(old?.description||'')}"></div><div class="field required"><label>Categoria</label><select id="f-category"></select></div><div class="field required"><label>Valor bruto (R$)</label><input id="f-gross" type="number" step="0.01" min="0.01" required value="${old?.gross||''}" placeholder="0,00"></div><div class="field"><label>Pagamento</label>${select('f-method',methods,old?.method||'pix')}</div><div class="field"><label>Situação</label>${select('f-status',[['pendente','Pendente'],['pago','Liquidado']],old?.status||'pendente')}</div><div class="field"><label>Profissional (se aplicável)</label>${select('f-professional',[['','Não se aplica'],...PEOPLE.map(p=>[p.id,p.name])],old?.professional||'')}</div><div class="field"><label>Taxa manual (R$), se conhecida</label><input id="f-fees" type="number" min="0" step="0.01" value="${old?.fees||0}"></div><div class="field wide"><label>Observações</label><textarea id="f-notes" maxlength="300">${esc(old?.notes||'')}</textarea></div></div><div class="helper warning">A tabela Stone oficial não foi fornecida. Qualquer taxa informada é um exemplo manual; não será buscada ou calculada automaticamente.</div><div id="f-preview" class="helper"></div><div class="drawer-footer"><button type="button" class="btn" data-action="closeDrawer">Cancelar</button><button class="btn btn-primary" type="submit">${old?'Salvar edição demonstrativa':'Registrar lançamento de exemplo'}</button></div></form>`);
 const f=$('transaction-form');f.dataset.editId=editId||'';updateCats();updateTransactionPreview();
}
function updateCats(){let type=$('f-kind');if(!type)return;let selected=state.tx.find(t=>t.id===$('transaction-form')?.dataset.editId)?.category;let cats=CATEGORIES[type.value]||[];$('f-category').innerHTML=cats.map(c=>`<option ${c===selected?'selected':''}>${esc(c)}</option>`).join('');}
function updateTransactionPreview(){if(!$('f-preview'))return;let gross=Number($('f-gross').value)||0,fees=Number($('f-fees').value)||0,net=$('f-kind').value==='entrada'?gross-fees:gross+fees;$('f-preview').innerHTML=`<b>Prévia de composição:</b> bruto ${money(gross)} · taxa ${money(fees)} · ${$('f-kind').value==='entrada'?'líquido a receber':'custo total'} <b>${money(net)}</b>.`;
}
function saveTransaction(){const kind=$('f-kind').value,description=$('f-description').value.trim(),gross=Number($('f-gross').value),fees=Number($('f-fees').value||0),date=$('f-date').value;
 if(!description||!date||!Number.isFinite(gross)||gross<=0||!Number.isFinite(fees)||fees<0||fees>=gross&&kind==='entrada'){notify('Confira descrição, data e valores: a taxa não pode consumir toda a entrada.');return;}
 const entry={id:'FIN-'+String(2000+state.revision),kind,date,description,category:$('f-category').value,gross,fees,net:Math.round((kind==='entrada'?gross-fees:gross+fees)*100)/100,method:$('f-method').value,status:$('f-status').value,professional:$('f-professional').value,stone:false,notes:$('f-notes').value};
 let edit=$('transaction-form').dataset.editId;if(edit){let index=state.tx.findIndex(x=>x.id===edit);if(index<0)return;entry.id=edit;state.tx[index]=entry;log('Edição de lançamento pendente',edit);}else{state.tx.unshift(entry);log('Novo lançamento fictício',entry.id);}
 closeDrawer();bump();notify('Operação registrada apenas nesta sessão de demonstração.');
}
function addMonths(date,n){const parts=date.split('-').map(Number);const day=parts[2];const d=new Date(Date.UTC(parts[0],parts[1]-1+n,1));const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();return [d.getUTCFullYear(),String(d.getUTCMonth()+1).padStart(2,'0'),String(Math.min(day,last)).padStart(2,'0')].join('-');}
function moneyCents(v){return Math.round(v*100);}
function newInstallments(){openDrawer('Programar compra parcelada',`<div class="helper">Crie as parcelas com seus vencimentos individuais. Nenhum valor será descontado do caixa até a baixa de cada compromisso.</div><form id="install-form"><div class="form-grid"><div class="field wide required"><label>Descrição da compra</label><input id="i-description" required maxlength="100" value="Equipamento demonstrativo"></div>${field('i-amount','Valor total sem juros (R$)','number','2000','min="0.01" step="0.01" required')}${field('i-count','Parcelas','number','4','min="2" max="36" required')}${field('i-interest','Juros totais (%) — opcional','number','0','min="0" max="100" step="0.01"')}${field('i-date','Primeiro vencimento','date','2026-12-10','required')}</div><div class="helper" id="inst-preview"></div><div class="drawer-footer"><button type="button" class="btn" data-action="closeDrawer">Cancelar</button><button class="btn btn-primary" type="submit">Criar parcelas (simulação)</button></div></form>`);updateInstallPreview();}
function calculateInstallments(){const amount=Number($('i-amount')?.value),count=Number($('i-count')?.value),interest=Number($('i-interest')?.value||0),date=$('i-date')?.value;if(!Number.isFinite(amount)||amount<=0||!Number.isInteger(count)||count<2||count>36||!Number.isFinite(interest)||interest<0||interest>100||!date)return null;const totalCents=moneyCents(amount*(1+interest/100)),base=Math.floor(totalCents/count),items=[];for(let i=0;i<count;i++)items.push({due:addMonths(date,i),amount:(base+(i===count-1?totalCents-base*count:0))/100});return items;}
function updateInstallPreview(){if(!$('inst-preview'))return;let a=calculateInstallments();$('inst-preview').innerHTML=a?`<b>${a.length} parcelas previstas:</b> ${a.map((x,i)=>`${i+1}/${a.length} ${shortDate(x.due)} — ${money(x.amount)}`).join('<br>')}`:'Preencha valor, quantidade, juros e primeira data para visualizar as parcelas.';}
function saveInstallments(){const items=calculateInstallments(),description=$('i-description').value.trim();if(!items||!description){notify('Confira os dados do parcelamento.');return;}let id=Date.now().toString().slice(-6);for(let i=0;i<items.length;i++){const item=items[i];state.installments.push({id:'PAR-'+id+'-'+(i+1),parent:description,index:i+1,total:items.length,due:item.due,amount:item.amount,status:'pendente'});}log('Parcelamento programado',description+' / '+items.length+' parcelas');closeDrawer();bump();notify('Parcelas futuras criadas, sem desconto imediato no caixa.');}
function payInstallment(id){const x=state.installments.find(v=>v.id===id);if(!x||x.status!=='pendente')return;const allowed=['analista','gerente'];if(!allowed.includes(state.role)){notify('Perfil sem permissão para baixar parcelas.');return;}
 if(!confirm(`Simular a baixa de ${money(x.amount)} em ${shortDate(x.due)}? A operação ficará somente em memória.`))return;
 x.status='pago';state.tx.unshift({id:'FIN-'+String(2500+state.revision),date:DEMO_DATE,description:x.parent+` (parcela ${x.index}/${x.total})`,kind:'saida',category:'Fornecedor de AASI',gross:x.amount,fees:0,net:x.amount,method:'pix',status:'pago',professional:'',stone:false,notes:'Baixa demonstrativa '+x.id});log('Baixa de parcela (demo)',id);bump();notify('Parcela baixada apenas na simulação; caixa demonstrativo atualizado.');}
function newRecurring(){openDrawer('Novo custo recorrente',`<form id="rec-form"><div class="helper">A recorrência cria compromissos futuros, nunca débitos automáticos.</div><div class="form-grid"><div class="field wide required"><label>Descrição</label><input id="rec-name" maxlength="100" required placeholder="Ex.: aluguel do software"></div>${field('rec-value','Valor previsto (R$)','number','699','min="0.01" step="0.01" required')}${field('rec-day','Dia do vencimento','number','10','min="1" max="28" required')}</div><div class="helper">Nesta V1, as regras são mensais e a geração de cada vencimento é manual.</div><div class="drawer-footer"><button type="button" class="btn" data-action="closeDrawer">Cancelar</button><button type="submit" class="btn btn-primary">Criar regra simulada</button></div></form>`)}
function saveRecurring(){let desc=$('rec-name').value.trim(),amount=Number($('rec-value').value),day=Number($('rec-day').value);if(!desc||amount<=0||!Number.isInteger(day)||day<1||day>28){notify('Informe descrição, valor positivo e dia entre 1 e 28.');return;}state.recurring.push({id:'REC-'+(100+state.revision),description:desc,amount,day,frequency:'mensal',status:'ativo'});log('Regra recorrente fictícia',desc);closeDrawer();bump();notify('Regra mensal adicionada à sessão demonstrativa.');}
function recurringNext(id){let r=state.recurring.find(x=>x.id===id);if(!r)return;let due='2026-12-'+String(r.day).padStart(2,'0');if(state.installments.some(x=>x.parent===r.description&&x.due===due)){notify('Próximo vencimento já gerado nesta sessão.');return;}
 state.installments.push({id:'PAR-REC-'+Date.now().toString().slice(-6),parent:r.description,index:1,total:1,due,amount:r.amount,status:'pendente'});log('Recorrência programada',r.description+' / '+due);bump();notify('Vencimento criado sem baixa automática.');}
function payTransaction(id){let t=state.tx.find(x=>x.id===id);if(!t||t.status!=='pendente')return;if(!['analista','gerente'].includes(state.role)){notify('Seu perfil não autoriza baixas.');return;}if(!confirm('Confirmar liquidação fictícia de '+money(t.net)+'?'))return;t.status='pago';log('Baixa demonstrativa',id);bump();notify('Baixa simulada registrada.');}
function requestReversal(id){const t=state.tx.find(x=>x.id===id);if(!t||t.status!=='pago'||!['analista','gerente'].includes(state.role))return;
 openDrawer('Solicitar estorno (demonstração)',`<div class="helper warning">Produção exigirá autorização da pessoa/perfil competente (processo informado da Dra. Simone), justificativa, operação reversa adequada, idempotência e auditoria. Não execute estornos reais aqui.</div><form id="reversal-form" data-id="${esc(id)}"><div class="paper"><b>${esc(t.description)}</b><p>Identificador ${esc(t.id)} · Valor ${money(t.net)}</p></div><div class="field required spaced"><label>Justificativa</label><textarea required id="rev-reason" maxlength="250" placeholder="Explique por que o estorno seria solicitado"></textarea></div><div class="drawer-footer"><button class="btn" type="button" data-action="closeDrawer">Cancelar</button><button class="btn btn-primary" type="submit">Registrar solicitação visual</button></div></form>`);
}
function saveReversal(){let form=$('reversal-form');let t=state.tx.find(x=>x.id===form.dataset.id),reason=$('rev-reason').value.trim();if(reason.length<10){notify('Informe uma justificativa de pelo menos 10 caracteres.');return;}if(!t)return;log('Solicitação de estorno (não executada)',t.id+' · '+reason);closeDrawer();bump();notify('Solicitação simulada em memória; transação mantida sem alterações.');}
function stoneDrawer(id){let s=state.stone.find(x=>x.id===id);if(!s)return;openDrawer('Conferir venda Stone',`<div class="helper warning">Informe valores somente de exemplo. Na operação real, extratos e tabelas oficiais deverão ser integrados e auditados.</div><form id="stone-form" data-id="${esc(id)}"><div class="kpi-strip"><div class="small-kpi"><small>Venda bruta</small><strong>${money(s.gross)}</strong></div><div class="small-kpi"><small>Referência</small><strong style="font-size:13px">${esc(s.sale)}</strong></div></div><div class="form-grid spaced">${field('s-fee','Taxa Stone informada (R$)','number',s.fee??'','min="0" step="0.01" required')}${field('s-advance','Taxa de antecipação (R$)','number',s.advance??0,'min="0" step="0.01" required')}${field('s-deposit','Depósito informado (R$)','number',s.deposit??'','min="0" step="0.01" required')}${field('s-date','Data do depósito','date',DEMO_DATE,'required')}</div><div class="helper" id="s-preview"></div><div class="drawer-footer"><button class="btn" type="button" data-action="closeDrawer">Cancelar</button><button class="btn btn-primary" type="submit">Conferir valores simulados</button></div></form>`);updateStonePreview();}
function updateStonePreview(){if(!$('s-preview'))return;const s=state.stone.find(x=>x.id===$('stone-form').dataset.id);let f=Number($('s-fee').value||0),a=Number($('s-advance').value||0),d=Number($('s-deposit').value||0);let expected=s.gross-f-a;$('s-preview').textContent=`Líquido esperado: ${money(expected)} · depósito informado: ${money(d)} · diferença: ${money(expected-d)}.`;}
function saveStone(){const form=$('stone-form'),s=state.stone.find(x=>x.id===form.dataset.id);let f=Number($('s-fee').value),a=Number($('s-advance').value),d=Number($('s-deposit').value);if(!s||![f,a,d].every(Number.isFinite)||Math.min(f,a,d)<0||f+a>s.gross){notify('Confira os valores da operadora; taxas não podem ultrapassar o bruto.');return;}s.fee=f;s.advance=a;s.deposit=d;s.status=Math.abs((s.gross-f-a)-d)<=0.01?'conciliado':'divergencia';s.note='Conferência demonstrativa sem extrato real';const linked=state.tx.find(t=>t.id===s.sale);if(linked&&linked.kind==='entrada'){linked.fees=s.status==='conciliado'?f+a:0;linked.net=s.status==='conciliado'?Math.round((s.gross-f-a)*100)/100:s.gross;linked.notes='Stone: valores exemplificativos; '+(s.status==='conciliado'?'conferido nesta simulação':'revisão pendente');}log('Conciliação manual (demo)',s.id+' · '+s.status);closeDrawer();bump();notify(s.status==='conciliado'?'Conciliação fictícia conferida.':'Divergência fictícia identificada; confira os valores.');}
function repasseScenario(){openDrawer('Simulador hipotético de repasse',`<div class="helper warning">A clínica ainda não confirmou se a base é bruta ou líquida nem o tratamento das taxas, estornos e parcelas. Nada será apurado oficialmente ou pago.</div><div class="field"><label>Profissional</label>${select('r-person',PEOPLE.filter(p=>p.rate!==null).map(p=>[p.id,p.name]))}</div><div class="field spaced"><label>Base HIPOTÉTICA da simulação (R$)</label><input id="r-base" type="number" step="0.01" min="0" value="1000"></div><div id="r-preview" class="helper"></div><div class="drawer-footer"><button class="btn btn-primary" data-action="closeDrawer">Concluir visualização</button></div>`);updateRepassePreview();}
function updateRepassePreview(){if(!$('r-preview'))return;let p=PEOPLE.find(x=>x.id===$('r-person').value),b=Number($('r-base').value||0);$('r-preview').innerHTML=`<b>${esc(p.name)}:</b> ${p.rate}% × ${money(b)} = <b>${money((p.rate/100)*Math.max(0,b))}</b> (cenário fictício, NÃO é valor devido).`;}
function ocrDrawer(){openDrawer('Comprovante e revisão manual',`<div class="helper warning">OCR REAL NÃO INTEGRADO: não há leitura automática de arquivos nesta V1. O arquivo permanece no dispositivo; usaremos um lançamento manual, sem qualquer envio ao servidor.</div><div class="field"><label>Selecione um comprovante fictício (opcional)</label><input id="ocr-file" type="file" accept="image/png,image/jpeg,application/pdf"></div><div id="ocr-info" class="helper">Nenhum arquivo selecionado.</div><div class="drawer-footer"><button class="btn" data-action="closeDrawer">Fechar</button><button class="btn btn-primary" data-action="ocrManual">Conferir manualmente no lançamento</button></div>`);}
function exportCSV(audit=false){if(audit||!['analista','gerente','desenvolvedor'].includes(state.role)){notify('Auditoria disponível somente na Central e exportação financeira restrita aos perfis autorizados.');return;}const rows=audit?[['Data','Ator (demo)','Evento','Detalhe'],...state.audit.map(a=>[a.date,a.who,a.action,a.detail])]:[['ID','Data','Descrição','Natureza','Categoria','Bruto','Taxas','Líquido','Situação','Método','Profissional'],...filteredTransactions().map(t=>[t.id,t.date,t.description,t.kind,t.category,t.gross,t.fees,t.net,t.status,t.method,getPerson(t.professional)])];
 const csv='\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=(audit?'auditoria':'financeiro')+'_audio_sa_DEMO_V1.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);log('Exportação local CSV','Somente dados fictícios');notify('Arquivo CSV fictício gerado no seu dispositivo.');}
function handleAction(action){if(!action)return;if(action==='new'){newTransaction();return;}if(action.startsWith('demo-')){demoAction(action);return;}if(action==='newInstallments'){newInstallments();return;}if(action==='newRecurring'){newRecurring();return;}if(action==='ocr'||action==='stoneImport'){ocrDrawer();return;}if(action==='ocrManual'){closeDrawer();newTransaction();notify('Revise manualmente todos os campos: OCR não foi executado.');return;}if(action==='closeDrawer'){closeDrawer();return;}if(action==='toggleTheme'){state.theme=state.theme==='dark'?'light':'dark';setTheme();return;}if(action==='csv'){exportCSV();return;}if(action==='print'){window.print();return;}if(action==='repasseScenario'){repasseScenario();return;}if(action==='stoneFirst'){let s=state.stone.find(x=>x.status!=='conciliado')||state.stone[0];stoneDrawer(s.id);return;}if(action==='lgpdNext'){if(!state.lgpdViewed)return;state.lgpdStep=2;render();notify('Visualização simulada concluída. Nenhum aceite foi coletado.');return;}if(action==='clearFilters'){state.search='';state.txStatus='todos';state.txKind='todos';state.dateFrom='';state.dateTo='';render();return;}if(action.startsWith('report:')){state.reportType=action.split(':')[1];render();return;}if(action.startsWith('stone:')){stoneDrawer(action.slice(6));return;}if((action.startsWith('pay:')||action.startsWith('edit:')||action.startsWith('reversal:')||action.startsWith('instpay:')||action.startsWith('recnext:')||action.startsWith('stone:'))&&!['desenvolvedor','analista','gerente'].includes(state.role)){notify('Ação não disponível para este perfil demonstrativo.');return;}if(action.startsWith('pay:')){payTransaction(action.slice(4));return;}if(action.startsWith('edit:')){newTransaction(action.slice(5));return;}if(action.startsWith('reversal:')){requestReversal(action.slice(9));return;}if(action.startsWith('instpay:')){payInstallment(action.slice(8));return;}if(action.startsWith('recnext:')){recurringNext(action.slice(8));return;}if(views[action]){go(action);return;}notify('Este recurso permanece demonstrativo. Nenhum serviço externo foi acionado.');}
document.addEventListener('click',e=>{const link=e.target.closest('[data-page]');if(link){e.preventDefault();go(link.dataset.page);return;}const btn=e.target.closest('[data-action]');if(btn){e.preventDefault();handleAction(btn.dataset.action);}});
document.addEventListener('submit',e=>{if(['transaction-form','install-form','rec-form','reversal-form','stone-form','demo-appointment-form','demo-patient-form','demo-term-form','demo-draft-form'].includes(e.target.id)){e.preventDefault();switch(e.target.id){case 'transaction-form':saveTransaction();break;case 'install-form':saveInstallments();break;case 'rec-form':saveRecurring();break;case 'reversal-form':saveReversal();break;case 'stone-form':saveStone();break;default:demoSave(e.target);break;}}});
document.addEventListener('input',e=>{if(['f-gross','f-fees','f-kind'].includes(e.target.id)){if(e.target.id==='f-kind')updateCats();updateTransactionPreview();}if(['i-amount','i-count','i-date','i-interest'].includes(e.target.id))updateInstallPreview();if(['s-fee','s-advance','s-deposit'].includes(e.target.id))updateStonePreview();if(['r-person','r-base'].includes(e.target.id))updateRepassePreview();if(e.target.id==='tx-search'){state.search=e.target.value;const pos=e.target.selectionStart;render();const f=$('tx-search');if(f){f.focus();f.setSelectionRange(pos,pos);}}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='lgpd-view'){state.lgpdViewed=e.target.checked;const next=document.querySelector('[data-action=lgpdNext]');if(next)next.disabled=!state.lgpdViewed;return;}if(id==='ocr-file'){$('ocr-info').textContent=e.target.files.length?'Arquivo selecionado localmente: '+e.target.files[0].name+' (não processado e não enviado).':'Nenhum arquivo selecionado.';return;}if(['tx-status','tx-kind','tx-from','tx-to'].includes(id)){const map={'tx-status':'txStatus','tx-kind':'txKind','tx-from':'dateFrom','tx-to':'dateTo'};state[map[id]]=e.target.value;render();}});
$('role-select').addEventListener('change',e=>{state.role=e.target.value;state.page=activePermission().includes(state.page)?state.page:activePermission()[0];render();notify('Perfil demonstrativo alterado. O controle real de auditoria é exclusivo da Central no XAMPP.');});
$('theme-toggle').addEventListener('click',()=>handleAction('toggleTheme'));
$('menu-toggle').addEventListener('click',()=> $('sidebar').classList.contains('is-open')?closeNav():openNav());$('mobile-scrim').addEventListener('click',closeNav);$('drawer-close').addEventListener('click',closeDrawer);$('drawer-backdrop').addEventListener('click',closeDrawer);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeNav();}});
window.addEventListener('hashchange',()=>{const requested=location.hash.replace(/^#\/?/,'').split(/[?&]/)[0];if(views[requested]&&activePermission().includes(requested)){state.page=requested;render();}});
const requested=location.hash.replace(/^#\/?/,'').split(/[?&]/)[0];if(views[requested])state.page=requested;setTheme();render();
if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));}
